<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';
require_once __DIR__.'/_helper.php';
require_once __DIR__.'/../includes/school_profile.php';
perpus_require_access();
$school=school_profile($pdo);
$school_logo=school_logo_url($pdo);
$kepala_nama=trim((string)($school['nama_kepala']??''));
$kepala_nip=trim((string)($school['nip_kepala']??''));
$petugas_nama=trim((string)(user_name()??''));
perpus_sync_members($pdo);

$today=date('Y-m-d');
$awal=(string)($_GET['awal']??date('Y-m-01'));
$akhir=(string)($_GET['akhir']??$today);
$jenis=(string)($_GET['jenis']??'ringkasan');
$q=trim((string)($_GET['q']??''));
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$awal))$awal=date('Y-m-01');
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$akhir))$akhir=$today;
if($awal>$akhir){[$awal,$akhir]=[$akhir,$awal];}
$allowed=['ringkasan','pengunjung','peminjaman','pengembalian','terlambat','kondisi'];
if(!in_array($jenis,$allowed,true))$jenis='ringkasan';

function laporan_csv(string $filename,array $headers,array $rows):never{
    header('Content-Type: text/csv; charset=UTF-8');
    header('Content-Disposition: attachment; filename="'.$filename.'"');
    echo "\xEF\xBB\xBF";
    $out=fopen('php://output','w');fputcsv($out,$headers,';');foreach($rows as $r)fputcsv($out,$r,';');fclose($out);exit;
}

$baseParams=['awal'=>$awal,'akhir'=>$akhir];
$like=$q!==''?"%$q%":'';
$pengunjung=[];$peminjaman=[];$pengembalian=[];$terlambat=[];$kondisi=[];

if($jenis==='pengunjung'){
    $sql="SELECT DATE_FORMAT(k.waktu_kunjungan,'%Y-%m-%d %H:%i:%s') waktu, s.nis,s.nisn,s.nama,mk.nama kelas,k.metode,COALESCE(u.nama,'-') petugas,k.keterangan FROM perpustakaan_kunjungan k JOIN siswa s ON s.id=k.siswa_id LEFT JOIN master_kelas mk ON mk.id=k.kelas_id LEFT JOIN users u ON u.id=k.petugas_id WHERE k.waktu_kunjungan>=? AND k.waktu_kunjungan<?";
    $params=[$awal.' 00:00:00',date('Y-m-d H:i:s',strtotime($akhir.' +1 day'))];
    if($q!==''){$sql.=" AND (s.nama LIKE ? OR s.nis LIKE ? OR s.nisn LIKE ? OR mk.nama LIKE ?)";$params=array_merge($params,[$like,$like,$like,$like]);}
    $sql.=' ORDER BY k.waktu_kunjungan DESC';$st=$pdo->prepare($sql);$st->execute($params);$pengunjung=$st->fetchAll();
    if(isset($_GET['format'])&&$_GET['format']==='csv') laporan_csv('laporan-pengunjung-'.$awal.'-'.$akhir.'.csv',['Waktu','NIS','NISN','Nama','Kelas','Metode','Petugas','Keterangan'],array_map(fn($r)=>[$r['waktu'],$r['nis'],$r['nisn'],$r['nama'],$r['kelas'],$r['metode'],$r['petugas'],$r['keterangan']],$pengunjung));
}
if($jenis==='peminjaman'||$jenis==='terlambat'){
    $sql="SELECT p.id,p.nomor_transaksi,p.tanggal_pinjam,p.tanggal_jatuh_tempo,p.status ps,a.kode_anggota,COALESCE(s.nama,g.nama) nama,d.id detail_id,b.judul,e.kode_eksemplar,d.jumlah FROM perpustakaan_peminjaman p JOIN perpustakaan_anggota a ON a.id=p.anggota_id LEFT JOIN siswa s ON s.id=a.siswa_id LEFT JOIN guru g ON g.id=a.guru_id JOIN perpustakaan_detail_peminjaman d ON d.peminjaman_id=p.id JOIN perpustakaan_buku b ON b.id=d.buku_id LEFT JOIN perpustakaan_eksemplar e ON e.id=d.eksemplar_id WHERE 1=1";
    $params=[];
    if($jenis==='terlambat'){$sql.=" AND d.status='dipinjam' AND p.tanggal_jatuh_tempo<=?";$params[]=$akhir;}else{$sql.=" AND p.tanggal_pinjam BETWEEN ? AND ?";$params=[$awal,$akhir];}
    if($q!==''){$sql.=" AND (p.nomor_transaksi LIKE ? OR a.kode_anggota LIKE ? OR s.nama LIKE ? OR g.nama LIKE ? OR b.judul LIKE ? OR e.kode_eksemplar LIKE ?)";$params=array_merge($params,[$like,$like,$like,$like,$like,$like]);}
    $sql.=' ORDER BY p.tanggal_pinjam DESC,p.id DESC,d.id ASC';$st=$pdo->prepare($sql);$st->execute($params);$peminjaman=$st->fetchAll();
    if(isset($_GET['format'])&&$_GET['format']==='csv'){
        $rows=array_map(fn($r)=>[$r['nomor_transaksi'],$r['nama'],$r['kode_anggota'],$r['judul'],$r['kode_eksemplar']?:$r['buku_id'],$r['tanggal_pinjam'],$r['tanggal_jatuh_tempo'],($r['ps']==='dipinjam'&&$r['tanggal_jatuh_tempo']<$today)?'Terlambat':$r['ps']],$peminjaman);
        laporan_csv('laporan-'.($jenis==='terlambat'?'terlambat':'peminjaman').'-'.$awal.'-'.$akhir.'.csv',['Transaksi','Peminjam','Kode Anggota','Judul','Kode Eksemplar','Tanggal Pinjam','Jatuh Tempo','Status'],$rows);
    }
}
if($jenis==='pengembalian'){
    $sql="SELECT d.tanggal_kembali,p.nomor_transaksi,COALESCE(s.nama,g.nama) nama,a.kode_anggota,b.judul,e.kode_eksemplar,d.kondisi_kembali,d.denda,d.keterangan FROM perpustakaan_detail_peminjaman d JOIN perpustakaan_peminjaman p ON p.id=d.peminjaman_id JOIN perpustakaan_anggota a ON a.id=p.anggota_id LEFT JOIN siswa s ON s.id=a.siswa_id LEFT JOIN guru g ON g.id=a.guru_id JOIN perpustakaan_buku b ON b.id=d.buku_id LEFT JOIN perpustakaan_eksemplar e ON e.id=d.eksemplar_id WHERE d.tanggal_kembali BETWEEN ? AND ?";
    $params=[$awal,$akhir];if($q!==''){$sql.=" AND (p.nomor_transaksi LIKE ? OR a.kode_anggota LIKE ? OR s.nama LIKE ? OR g.nama LIKE ? OR b.judul LIKE ? OR e.kode_eksemplar LIKE ?)";$params=array_merge($params,[$like,$like,$like,$like,$like,$like]);}$sql.=' ORDER BY d.tanggal_kembali DESC,d.id DESC';$st=$pdo->prepare($sql);$st->execute($params);$pengembalian=$st->fetchAll();
    if(isset($_GET['format'])&&$_GET['format']==='csv') laporan_csv('laporan-pengembalian-'.$awal.'-'.$akhir.'.csv',['Tanggal Kembali','Transaksi','Peminjam','Kode Anggota','Judul','Kode Eksemplar','Kondisi','Denda','Keterangan'],array_map(fn($r)=>[$r['tanggal_kembali'],$r['nomor_transaksi'],$r['nama'],$r['kode_anggota'],$r['judul'],$r['kode_eksemplar'],$r['kondisi_kembali'],$r['denda'],$r['keterangan']],$pengembalian));
}
if($jenis==='kondisi'){
    $sql="SELECT e.status,e.kondisi,COUNT(*) jumlah FROM perpustakaan_eksemplar e JOIN perpustakaan_buku b ON b.id=e.buku_id WHERE b.status='tersedia' GROUP BY e.status,e.kondisi ORDER BY e.status,e.kondisi";$kondisi=$pdo->query($sql)->fetchAll();
    if(isset($_GET['format'])&&$_GET['format']==='csv') laporan_csv('laporan-kondisi-eksemplar-'.$today.'.csv',['Status','Kondisi','Jumlah'],array_map(fn($r)=>[$r['status'],$r['kondisi'],$r['jumlah']],$kondisi));
}

$stats=[];
$stats['judul']=(int)$pdo->query("SELECT COUNT(*) FROM perpustakaan_buku WHERE status='tersedia'")->fetchColumn();
$stats['eksemplar']=(int)$pdo->query("SELECT COUNT(*) FROM perpustakaan_eksemplar e JOIN perpustakaan_buku b ON b.id=e.buku_id WHERE b.status='tersedia'")->fetchColumn();
$stats['tersedia']=(int)$pdo->query("SELECT COUNT(*) FROM perpustakaan_eksemplar e JOIN perpustakaan_buku b ON b.id=e.buku_id WHERE b.status='tersedia' AND e.status='tersedia'")->fetchColumn();
$stats['dipinjam']=(int)$pdo->query("SELECT COUNT(*) FROM perpustakaan_eksemplar e JOIN perpustakaan_buku b ON b.id=e.buku_id WHERE b.status='tersedia' AND e.status='dipinjam'")->fetchColumn();
$stats['rusak']=(int)$pdo->query("SELECT COUNT(*) FROM perpustakaan_eksemplar e JOIN perpustakaan_buku b ON b.id=e.buku_id WHERE b.status='tersedia' AND e.status='rusak'")->fetchColumn();
$stats['hilang']=(int)$pdo->query("SELECT COUNT(*) FROM perpustakaan_eksemplar e JOIN perpustakaan_buku b ON b.id=e.buku_id WHERE b.status='tersedia' AND e.status='hilang'")->fetchColumn();
$st=$pdo->prepare("SELECT COUNT(*) FROM perpustakaan_kunjungan WHERE waktu_kunjungan>=? AND waktu_kunjungan<?");$st->execute([$awal.' 00:00:00',date('Y-m-d H:i:s',strtotime($akhir.' +1 day'))]);$stats['kunjungan']=(int)$st->fetchColumn();
$st=$pdo->prepare("SELECT COUNT(DISTINCT p.id) FROM perpustakaan_peminjaman p WHERE p.tanggal_pinjam BETWEEN ? AND ?");$st->execute([$awal,$akhir]);$stats['transaksi']=(int)$st->fetchColumn();
$st=$pdo->query("SELECT COUNT(*) FROM perpustakaan_detail_peminjaman d JOIN perpustakaan_peminjaman p ON p.id=d.peminjaman_id WHERE d.status='dipinjam' AND p.tanggal_jatuh_tempo<CURDATE()");$stats['terlambat']=(int)$st->fetchColumn();

$page_title='Laporan Perpustakaan';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
$qs=function(string $j)use($awal,$akhir,$q){return http_build_query(['jenis'=>$j,'awal'=>$awal,'akhir'=>$akhir,'q'=>$q]);};
?>
<main class="main"><header class="topbar"><div class="topbar-title">Laporan Perpustakaan</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><style>
