gunjung, transaksi, pengembalian, keterlambatan, dan kondisi setiap eksemplar.</p></div><div class="print-header"><div class="kop"><?php if($school_logo): ?><img class="logo" src="<?=e($school_logo)?>" alt="Logo Sekolah"><?php else: ?><div class="logo"></div><?php endif; ?><div class="school"><div class="name"><?=e($school['nama_sekolah']??'Sekolah')?></div><div class="sub"><?=e($school['alamat']??'')?><?=!empty($school['desa'])?' · '.e($school['desa']):''?><?=!empty($school['kecamatan'])?' · '.e($school['kecamatan']):''?><?=!empty($school['kabupaten'])?' · '.e($school['kabupaten']):''?></div><?php if(!empty($school['website'])||!empty($school['telepon'])):?><div class="sub"><?=!empty($school['website'])?e($school['website']):''?><?=(!empty($school['website'])&&!empty($school['telepon']))?' · ':''?><?=!empty($school['telepon'])?'Telp. '.e($school['telepon']):''?></div><?php endif;?></div></div><div class="title">Laporan Perpustakaan — <?=e(ucwords($jenis))?></div><div class="period">Periode <?=e($awal)?> s.d. <?=e($akhir)?> · Dicetak <?=e(date('d-m-Y H:i'))?> WIB</div></div>
<div class="filters no-print"><form method="get" style="display:contents"><input type="hidden" name="jenis" value="<?=e($jenis)?>"><div><label class="fw-bold small">Dari</label><input class="form-control" type="date" name="awal" value="<?=e($awal)?>"></div><div><label class="fw-bold small">Sampai</label><input class="form-control" type="date" name="akhir" value="<?=e($akhir)?>"></div><div><label class="fw-bold small">Cari</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Nama, transaksi, judul, kode..."></div><button class="btn btn-primary"><i class="bi bi-funnel"></i> Terapkan</button><button type="button" class="btn btn-outline-secondary" onclick="window.print()"><i class="bi bi-printer"></i> Cetak / PDF</button></form></div>
<div class="tabs no-print"><?php foreach(['ringkasan'=>'Ringkasan','pengunjung'=>'Pengunjung','peminjaman'=>'Peminjaman','pengembalian'=>'Pengembalian','terlambat'=>'Belum Kembali / Terlambat','kondisi'=>'Kondisi Eksemplar'] as $k=>$v):?><a class="<?=$jenis===$k?'active':''?>" href="?<?=e($qs($k))?>"><?=e($v)?></a><?php endforeach;?></div>
<?php if($jenis==='ringkasan'):?><div class="print-summary"><table><tbody><tr><td><strong>Judul aktif</strong></td><td><?=number_format($stats['judul'])?></td><td><strong>Total eksemplar</strong></td><td><?=number_format($stats['eksemplar'])?></td></tr><tr><td><strong>Tersedia</strong></td><td><?=number_format($stats['tersedia'])?></td><td><strong>Dipinjam</strong></td><td><?=number_format($stats['dipinjam'])?></td></tr><tr><td><strong>Rusak</strong></td><td><?=number_format($stats['rusak'])?></td><td><strong>Hilang</strong></td><td><?=number_format($stats['hilang'])?></td></tr><tr><td><strong>Kunjungan</strong></td><td><?=number_format($stats['kunjungan'])?></td><td><strong>Transaksi peminjaman</strong></td><td><?=number_format($stats['transaksi'])?></td></tr><tr><td><strong>Eksemplar terlambat</strong></td><td colspan="3"><?=number_format($stats['terlambat'])?></td></tr></tbody></table></div><div class="stats"><div class="stat"><div class="num"><?=number_format($stats['judul'])?></div><div class="lab">JUDUL AKTIF</div></div><div class="stat"><div class="num"><?=number_format($stats['eksemplar'])?></div><div class="lab">EKSEMPLAR</div></div><div class="stat"><div class="num"><?=number_format($stats['tersedia'])?></div><div class="lab">TERSEDIA</div></div><div class="stat"><div class="num"><?=number_format($stats['dipinjam'])?></div><div class="lab">DIPINJAM</div></div><div class="stat"><div class="num"><?=number_format($stats['rusak'])?></div><div class="lab">RUSAK</div></div><div class="stat"><div class="num"><?=number_format($stats['hilang'])?></div><div class="lab">HILANG</div></div></div><div class="card summary-detail"><h5>Periode <?=e($awal)?> s.d. <?=e($akhir)?></h5><div class="row g-3 mt-1"><div class="col-md-3"><strong><?=number_format($stats['kunjungan'])?></strong><div class="text-muted small">Kunjungan</div></div><div class="col-md-3"><strong><?=number_format($stats['transaksi'])?></strong><div class="text-muted small">Transaksi peminjaman</div></div><div class="col-md-3"><strong><?=number_format($stats['terlambat'])?></strong><div class="text-muted small">Eksemplar masih terlambat</div></div></div></div><?php elseif($jenis==='pengunjung'):?><div class="card"><div class="d-flex justify-content-between align-items-center mb-2"><h5>Rekap Pengunjung</h5><a class="btn btn-sm btn-success no-print" href="?<?=e($qs('pengunjung'))?>&format=csv"><i class="bi bi-filetype-csv"></i> CSV</a></div><div class="table-wrap"><table class="table table-hover"><thead><tr><th>Waktu</th><th>Nama</th><th>NIS/NISN</th><th>Kelas</th><th>Metode</th><th>Petugas</th><th>Keterangan</th></tr></thead><tbody><?php foreach($pengunjung as $r):?><tr><td><?=e($r['waktu'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['nis'])?> / <?=e($r['nisn'])?></td><td><?=e($r['kelas'])?></td><td><?=e($r['metode'])?></td><td><?=e($r['petugas'])?></td><td><?=e($r['keterangan'])?></td></tr><?php endforeach;if(!$pengunjung):?><tr><td colspan="7" class="text-center text-muted">Tidak ada data.</td></tr><?php endif;?></tbody></table></div></div><?php elseif($jenis==='peminjaman'||$jenis==='terlambat'):?><div class="card"><div class="d-flex justify-content-between align-items-center mb-2"><h5><?= $jenis==='terlambat'?'Buku Belum Kembali / Terlambat':'Rekap Peminjaman' ?></h5><a class="btn btn-sm btn-success no-print" href="?<?=e($qs($jenis))?>&format=csv"><i class="bi bi-filetype-csv"></i> CSV</a></div><div class="table-wrap"><table class="table table-hover"><thead><tr><th>Transaksi</th><th>Peminjam</th><th>Judul</th><th>Eksemplar</th><th>Pinjam</th><th>Jatuh Tempo</th><th>Status</th></tr></thead><tbody><?php foreach($peminjaman as $r):$sts=($r['ps']==='dipinjam'&&$r['tanggal_jatuh_tempo']<$today)?'terlambat':($r['ps']==='dipinjam'?'dipinjam':$r['ps']);?><tr><td><?=e($r['nomor_transaksi'])?></td><td><?=e($r['nama'])?><div class="text-muted small"><?=e($r['kode_anggota'])?></div></td><td><?=e($r['judul'])?></td><td><strong><?=e($r['kode_eksemplar']?:'-')?></strong></td><td><?=e($r['tanggal_pinjam'])?></td><td><?=e($r['tanggal_jatuh_tempo'])?></td><td><?=e(perpus_label_status($sts))?></td></tr><?php endforeach;if(!$peminjaman):?><tr><td colspan="7" class="text-center text-muted">Tidak ada data.</td></tr><?php endif;?></tbody></table></div></div><?php elseif($jenis==='pengembalian'):?><div class="card"><div class="d-flex justify-content-between align-items-center mb-2"><h5>Rekap Pengembalian</h5><a class="btn btn-sm btn-success no-print" href="?<?=e($qs('pengembalian'))?>&format=csv"><i class="bi bi-filetype-csv"></i> CSV</a></div><div class="table-wrap"><table class="table table-hover"><thead><tr><th>Tanggal</th><th>Transaksi</th><th>Peminjam</th><th>Judul</th><th>Eksemplar</th><th>Kondisi</th><th>Denda</th><th>Keterangan</th></tr></thead><tbody><?php foreach($pengembalian as $r):?><tr><td><?=e($r['tanggal_kembali'])?></td><td><?=e($r['nomor_transaksi'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['judul'])?></td><td><?=e($r['kode_eksemplar']?:'-')?></td><td><?=e(ucwords(str_replace('_',' ',$r['kondisi_kembali']??'-')))?></td><td>Rp <?=number_format((float)$r['denda'],2,',','.')?></td><td><?=e($r['keterangan'])?></td></tr><?php endforeach;if(!$pengembalian):?><tr><td colspan="8" class="text-center text-muted">Tidak ada data.</td></tr><?php endif;?></tbody></table></div></div><?php else: ?><div class="card"><div class="d-flex justify-content-between align-items-center mb-2"><h5>Rekap Kondisi Eksemplar</h5><a class="btn btn-sm btn-success no-print" href="?<?=e($qs('kondisi'))?>&format=csv"><i class="bi bi-filetype-csv"></i> CSV</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Status</th><th>Kondisi</th><th>Jumlah</th></tr></thead><tbody><?php foreach($kondisi as $r):?><tr><td><?=e(ucwords(str_replace('_',' ',$r['status'])))?></td><td><?=e(ucwords(str_replace('_',' ',$r['kondisi'])))?></td><td><strong><?=number_format((int)$r['jumlah'])?></strong></td></tr><?php endforeach;if(!$kondisi):?><tr><td colspan="3" class="text-center text-muted">Tidak ada data.</td></tr><?php endif;?></tbody></table></div></div><?php endif;?><div class="print-footer"><div class="signatures"><div class="sig"><div class="place"><?=e($school['kabupaten']??'')?>, <?=e(date('d-m-Y'))?></div><div>Kepala Sekolah</div><div class="space"></div><div class="name"><?=e($kepala_nama?:'........................................................')?></div><?php if($kepala_nip):?><div class="nip">NIP. <?=e($kepala_nip)?></div><?php endif;?></div><div class="sig"><div class="place">Petugas Perpustakaan</div><div>&nbsp;</div><div class="space"></div><div class="name"><?=e($petugas_nama?:'........................................................')?></div></div></div></div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';
